> > +		allowed[0] |= CMDQ_TLBI_0_VMID;
> > +		allowed[1] |= CMDQ_TLBI_1_LEAF | CMDQ_TLBI_1_TTL |
> > +			      CMDQ_TLBI_1_VA_MASK;
