 lib/Kconfig.debug          |  10 +
 lib/tests/Makefile         |   3 +
 lib/tests/lineinfo_kunit.c | 855 +++++++++++++++++++++++++++++++++++++
 4 files changed, 870 insertions(+)
 create mode 100644 lib/tests/lineinfo_kunit.c

diff --git a/kernel/kallsyms.c b/kernel/kallsyms.c
